test("loads .env.example with quoted values intact", () => {
  const cfg = loadConfig(readFileSync(".env.example", "utf8"));
  assert.equal(cfg.port, 8080);
  assert.equal(cfg.host, "0.0.0.0");
  assert.equal(cfg.appName, "Order Service");
  assert.equal(cfg.debug, false);
  assert.equal(cfg.motd, "hello # not a comment");
});

test("strips comments and whitespace outside quotes", () => {
  const env = parseEnvFile(
    ["# a comment", "", "HOST=db.internal # trailing", "  PORT = 9090  ", "export TOKEN=abc"].join("\n"),
  );
  assert.deepEqual(env, { HOST: "db.internal", PORT: "9090", TOKEN: "abc" });
});

test("handles escapes and quotes inside values", () => {
  const env = parseEnvFile(['GREETING="line\\none"', "LITERAL='raw\\nvalue'", 'QUOTED="say \\"hi\\""'].join("\n"));
  assert.equal(env.GREETING, "line\none");
  assert.equal(env.LITERAL, "raw\\nvalue");
  assert.equal(env.QUOTED, 'say "hi"');
});

test("rejects an invalid PORT", () => {
  assert.throws(() => loadConfig("PORT=not-a-number\n"), /invalid PORT/);
});

